import{_ as a,o as t,c as r,a1 as n}from"./chunks/framework.Ccs17H5l.js";const h=JSON.parse('{"title":"EIF1 : la version 1 du format EIF","description":"","frontmatter":{},"headers":[],"relativePath":"reference/formats/eif-v1.md","filePath":"reference/formats/eif-v1.md"}'),s={name:"reference/formats/eif-v1.md"};function i(l,e,o,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="eif1-la-version-1-du-format-eif" tabindex="-1">EIF1 : la version 1 du format EIF <a class="header-anchor" href="#eif1-la-version-1-du-format-eif" aria-label="Permalink to &quot;EIF1 : la version 1 du format EIF&quot;">​</a></h1><p>EIF1 est la seule version du <a href="./eif.html">format EIF</a> pour l&#39;instant. Un fichier est composé d&#39;un en-tête de 8 octets, suivi des pixels.</p><h2 id="contenu-du-fichier" tabindex="-1">Contenu du fichier <a class="header-anchor" href="#contenu-du-fichier" aria-label="Permalink to &quot;Contenu du fichier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Position (octets)</th><th>Taille</th><th>Nom</th><th>Contenu</th></tr></thead><tbody><tr><td>0 à 3</td><td>4</td><td>Identifiant</td><td>les quatre caractères <code>EIF1</code> (octets <code>0x45 0x49 0x46 0x31</code>)</td></tr><tr><td>4 à 5</td><td>2</td><td>Largeur</td><td>largeur en pixels, entier de 16 bits</td></tr><tr><td>6 à 7</td><td>2</td><td>Hauteur</td><td>hauteur en pixels, entier de 16 bits</td></tr><tr><td>8 à la fin</td><td>largeur × hauteur × 2</td><td>Pixels</td><td>un pixel par groupe de 2 octets, en <a href="./rgb565.html">RGB 565</a></td></tr></tbody></table><p>La taille totale d&#39;un fichier est donc <code>8 + largeur × hauteur × 2</code> octets.</p><h2 id="ordre-des-octets" tabindex="-1">Ordre des octets <a class="header-anchor" href="#ordre-des-octets" aria-label="Permalink to &quot;Ordre des octets&quot;">​</a></h2><p>Tous les nombres de plus d&#39;un octet sont écrits avec l&#39;octet de poids faible en premier (<em>petit-boutiste</em>, ou <em>little-endian</em>). C&#39;est l&#39;ordre natif du processeur de la calculatrice, ce qui permet d&#39;envoyer les pixels à l&#39;écran sans les réorganiser.</p><p>Exemple : une largeur de 300 vaut <code>0x012C</code> ; elle est écrite <code>0x2C 0x01</code>.</p><h2 id="ordre-des-pixels" tabindex="-1">Ordre des pixels <a class="header-anchor" href="#ordre-des-pixels" aria-label="Permalink to &quot;Ordre des pixels&quot;">​</a></h2><p>Les pixels sont rangés ligne par ligne, de haut en bas, et dans chaque ligne de gauche à droite. Le premier pixel est celui du coin en haut à gauche.</p><h2 id="exemple-complet" tabindex="-1">Exemple complet <a class="header-anchor" href="#exemple-complet" aria-label="Permalink to &quot;Exemple complet&quot;">​</a></h2><p>Une image de 2 pixels de large et 1 de haut : un pixel rouge, puis un pixel bleu.</p><ul><li>rouge pur en RGB 565 : <code>0xF800</code>, écrit <code>0x00 0xF8</code></li><li>bleu pur en RGB 565 : <code>0x001F</code>, écrit <code>0x1F 0x00</code></li></ul><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>45 49 46 31   identifiant « EIF1 »</span></span>
<span class="line"><span>02 00         largeur : 2</span></span>
<span class="line"><span>01 00         hauteur : 1</span></span>
<span class="line"><span>00 F8         pixel 1 : rouge</span></span>
<span class="line"><span>1F 00         pixel 2 : bleu</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Le fichier fait 12 octets : 8 d&#39;en-tête et 2 × 1 × 2 = 4 de pixels.</p><h2 id="transparence" tabindex="-1">Transparence <a class="header-anchor" href="#transparence" aria-label="Permalink to &quot;Transparence&quot;">​</a></h2><p>Le format ne gère pas la transparence : chaque pixel est une couleur pleine. Lors de la conversion d&#39;un PNG, les pixels totalement transparents (opacité à 0) deviennent blancs. Une opacité partielle est ignorée : la couleur du pixel est gardée telle quelle.</p><h2 id="ce-que-la-lecture-verifie-et-ce-qu-elle-ne-verifie-pas" tabindex="-1">Ce que la lecture vérifie, et ce qu&#39;elle ne vérifie pas <a class="header-anchor" href="#ce-que-la-lecture-verifie-et-ce-qu-elle-ne-verifie-pas" aria-label="Permalink to &quot;Ce que la lecture vérifie, et ce qu&#39;elle ne vérifie pas&quot;">​</a></h2><p><code>ImageLoader</code> contrôle que le fichier fait au moins 8 octets et que l&#39;identifiant est connu. Il ne contrôle pas que le nombre de pixels correspond à la largeur et à la hauteur annoncées : un fichier tronqué est accepté. Les fichiers produits par la compilation sont toujours complets, donc ce n&#39;est un risque que pour un fichier écrit ou modifié à la main.</p><h2 id="ou-est-le-code" tabindex="-1">Où est le code <a class="header-anchor" href="#ou-est-le-code" aria-label="Permalink to &quot;Où est le code&quot;">​</a></h2><ul><li>Écriture : <code>convert_image</code> dans <a href="https://github.com/Oignontom8283/eadkp/blob/dev/src/builder.rs" target="_blank" rel="noreferrer">builder.rs</a></li><li>Lecture et affichage : la structure <code>Eif1</code> dans <a href="https://github.com/Oignontom8283/eadkp/blob/dev/src/image.rs" target="_blank" rel="noreferrer">image.rs</a></li></ul>`,21)])])}const f=a(s,[["render",i]]);export{h as __pageData,f as default};
